+			return false;
+		off++;
+
+		if ((c & DNS_COMPRESS_PTR_MASK) == DNS_COMPRESS_PTR_MASK) {
+			if (bpf_skb_load_bytes(skb, off, &c, sizeof(c)))
+				return false;
+			off++;
+			*cursor = off;
