+                  to={`/nodes/${nodeID}`}
+                  className={cn(
+                    'inline-flex items-center gap-1.5 rounded-md border px-2 py-0.5 font-mono text-xs transition-colors hover:bg-muted',
+                    isVersionUndeclared(row, g.version)
