+                      : 'border-border/60 text-foreground/80 hover:border-primary/30',
+                  )}
+                >
+                  {nodeID}
+                  <span className="text-muted-foreground/60">
+                    {displayVersionIdentity(g.version)}
+                  </span>
+                </Link>
+              )),
+            )}
+          </div>
+        </div>
+      )}
+    </div>
+  );
+}
